CustomField.formula:
IF(DATE(YEAR(TODAY()),1,1) < Resource_User_Record__r.StartDate__c && Resource_User_Record__r.StartDate__c < DATE(YEAR(TODAY()),12,31),
(5*(FLOOR((fxLatestWorkDay__c - DATE(1900,1,8))/7 )) + MIN(5,MOD(fxLatestWorkDay__c - DATE(1900,1,8),7))) - (5*(FLOOR((Resource_User_Record__r.StartDate__c - DATE(1900,1,8))/7)) + MIN(5,MOD(Resource_User_Record__r.StartDate__c - DATE(1900,1,8),7)))+1 ,
/*calculates # business days if Resource starts during year*/
(5*(FLOOR((fxLatestWorkDay__c - DATE(1900,1,8))/7 )) + MIN(5,MOD(fxLatestWorkDay__c - DATE(1900,1,8),7))) - (5*(FLOOR((DATE(YEAR(TODAY()),1,1) - DATE(1900,1,8))/7)) + MIN(5,MOD(DATE(YEAR(TODAY()),1,1) - DATE(1900,1,8),7)))+1)
/*calculates standard # business days during year*/
